#!/usr/bin/env python3
"""Regenerate expected.txt for tests/fixtures/unicode_cat/main.xu.

Run from this directory:  python3 gen.py | diff expected.txt -

The rune list (22 boundary + 200 fixed-seed random) and the 7-function
semantics must match both `src/unicode` (generated by
scripts/gen_unicode_tables.py) and main.xu exactly.

Classification is done by Unicode category set, NOT by Python's isalpha family
(the task requires Go semantics; Python's isspace/isdigit differ):
    is_digit  = category == 'Nd'
    is_letter = category in {Lu,Ll,Lt,Lm,Lo}
    is_space  = category == 'Zs' or r in {9,10,11,12,13,32}
    is_upper  = category == 'Lu'
    is_lower  = category == 'Ll'

Case mapping targets Go's unicode.ToUpper/ToLower (the SIMPLE single-rune
mapping). We take Python's chr.upper()/chr.lower() restricted to single-char
results, then patch the small residue where Go's simple mapping differs from
Python's single-char full mapping (see scripts/gen_unicode_tables.py):
    U+0130 -> U+0069 (lower)
    Greek YPOGEGRAMMENI uppercase (U+1F80..1F8F, U+1F90..1F9F, U+1FA0..1FAF,
    U+1FB3, U+1FC3, U+1FF3).
"""

import random
import unicodedata

SEED = 20260815
ASCII_SPACE = {0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x20}

BOUNDARY = [0x0009, 0x0020, 0x0030, 0x0041, 0x005A, 0x0061, 0x007A, 0x00B5,
            0x00DF, 0x0130, 0x0131, 0x017F, 0x03A3, 0x03C3, 0x0410, 0x044F,
            0x4E00, 0x4E8C, 0xAC00, 0xD7A3, 0x1F600, 0x10FFFF]


def _upper_overrides():
    overrides = {}
    for base in (0x1F80, 0x1F90, 0x1FA0):
        for i in range(8):
            overrides[base + i] = base + i + 8
    for src, dst in ((0x1FB3, 0x1FBC), (0x1FC3, 0x1FCC), (0x1FF3, 0x1FFC)):
        overrides[src] = dst
    return overrides


UPPER_OVERRIDES = _upper_overrides()
LOWER_OVERRIDES = {0x0130: 0x0069}


def is_surrogate(r):
    return 0xD800 <= r <= 0xDFFF


def category(r):
    return unicodedata.category(chr(r))


def simple_upper(r):
    u = chr(r).upper()
    if len(u) == 1:
        return ord(u)
    return UPPER_OVERRIDES.get(r, r)


def simple_lower(r):
    l = chr(r).lower()
    if len(l) == 1:
        return ord(l)
    return LOWER_OVERRIDES.get(r, r)


def random_runes():
    rng = random.Random(SEED)
    out = []
    seen = set()
    while len(out) < 200:
        r = rng.randrange(0x110000)
        if is_surrogate(r) or r in seen:
            continue
        seen.add(r)
        out.append(r)
    return out


def fields(r):
    c = category(r)
    is_digit = c == 'Nd'
    is_letter = c in ('Lu', 'Ll', 'Lt', 'Lm', 'Lo')
    is_space = c == 'Zs' or r in ASCII_SPACE
    is_upper = c == 'Lu'
    is_lower = c == 'Ll'
    up = simple_upper(r)
    low = simple_lower(r)
    return (is_digit, is_letter, is_space, is_upper, is_lower, up, low)


def main():
    runes = BOUNDARY + random_runes()
    for r in runes:
        d, l, s, u, lo, up, low = fields(r)
        print('%d %s %s %s %s %s %d %d' % (
            r, str(d).lower(), str(l).lower(), str(s).lower(),
            str(u).lower(), str(lo).lower(), up, low))


if __name__ == '__main__':
    main()
